"use strict";

function interpolateWordsTimes(lineText, lineStartTime, lineEndTime, firstWordIndex) {
  // TODO: refactor to split via regex on space
  var wordsList = lineText.split(' ');

  if (lineStartTime === lineEndTime) {
    return wordsList.map(function (word, index) {
      return {
        start: lineStartTime,
        end: lineEndTime,
        text: word,
        index: index + firstWordIndex
      };
    });
  } else {
    var numberOfWords = wordsList.length; //10
    // console.log('numberOfWords', numberOfWords);

    var duration = lineEndTime - lineStartTime; //35

    var unit = duration / numberOfWords; //3.5

    var list = new Array(numberOfWords);
    list[0] = lineStartTime;
    var acc = 0;
    var newList = Array.from(list, function (x, i) {
      acc += unit;
      return acc;
    });
    var newListWithOffset = newList.map(function (l) {
      return l + lineStartTime;
    }); // console.log('newListWithOffset', newListWithOffset);

    var wordsListWordsResults = newListWithOffset.map(function (time, index) {
      return {
        text: wordsList[index],
        start: time,
        end: time,
        index: index + firstWordIndex
      };
    });
    return wordsListWordsResults;
  }
}

module.exports = interpolateWordsTimes;