"use strict";

var removeCarriageReturnFromString = function removeCarriageReturnFromString(refText) {
  return refText.trim().replace(/\n\n/g, ' ').replace(/\n/g, ' ');
};

var removeExtraWhiteSpaces = function removeExtraWhiteSpaces(text) {
  return text.trim().replace(/\s\s+/g, ' ');
};

var splitOnWhiteSpaces = function splitOnWhiteSpaces(text) {
  return removeExtraWhiteSpaces(text).split(' ');
};

function convertTextStringToArrayList(refText) {
  var transcriptTextWithoutLineBreaks = removeCarriageReturnFromString(refText); // const transcriptTextArray = transcriptTextWithoutLineBreaks.split(' ');

  var transcriptTextArray = splitOnWhiteSpaces(transcriptTextWithoutLineBreaks);
  return transcriptTextArray;
}

module.exports = convertTextStringToArrayList; // module.exports.removeCarriageReturnFromString = removeCarriageReturnFromString;
